import{XO_CONFIG as s}from"./config.min.js";import{slotOf as h}from"./playas.min.js";export const KINDS=Object.freeze(["fifty","pick","catch","sack","tackle","release"]);export function ballEvent(e,r){return!e||!r||!r.thrown||!r.holder||r.holder===e.holder||e.holder&&e.thrown?null:{kind:r.team===0?"catch":"pick",hero:r.holder,partner:null}}export function tackleKind({carrier:e,threw:r,ran:n}){return e==="qb"&&!r&&!n?"sack":"tackle"}export function delayFor(e){const r=s.moments.after[e];return Number.isFinite(r)&&r>0?r:0}export function involves(e,r){return!!r&&(e.hero===r||e.partner===r)}export function rankMoments(e,r=null,n=s.moments.keep){const i=e.some(t=>t.kind!=="release"),a=e.filter(t=>t.kind!=="release"||!i||involves(t,r)),c=t=>t.kind==="release"?2:involves(t,r)?0:1;return a.map((t,o)=>({m:t,i:o})).sort((t,o)=>c(t.m)-c(o.m)||KINDS.indexOf(t.m.kind)-KINDS.indexOf(o.m.kind)||(t.m.at||0)-(o.m.at||0)||t.i-o.i).slice(0,Math.max(0,n)).map(({m:t})=>t)}export const KIND_NAMES=Object.freeze({fifty:"Fifty",pick:"Interception",catch:"Catch",sack:"Sack",tackle:"Tackle",release:"Throw"});export function photoTitle(e){return KIND_NAMES[e]?`The ${KIND_NAMES[e].toLowerCase()}`:"The photo"}export function photoCaption(e,r=null){const n=t=>!!r&&t===r,i=t=>n(t)?"you":t==="qb"?"the quarterback":h(t).phrase,a=t=>{const o=i(t);return o[0].toUpperCase()+o.slice(1)},c=(t,o)=>n(e.hero)?t:`${a(e.hero)} ${o}`;switch(e.kind){case"catch":return c("You make the catch.","makes the catch.");case"pick":return c("You pick it off.","picks it off.");case"fifty":return c("You go in for fifty.","goes in for fifty.");case"release":{const t=e.partner?` to ${i(e.partner)}`:"";return c(`You let it fly${t}.`,`lets it fly${t}.`)}case"tackle":return e.partner?n(e.partner)?`You bring down ${i(e.hero)}.`:n(e.hero)?`${a(e.partner)} brings you down.`:`${a(e.partner)} brings down ${i(e.hero)}.`:`${a(e.hero)} ${n(e.hero)?"are":"is"} brought down.`;case"sack":return e.partner?n(e.partner)?"You sack the quarterback.":`${a(e.partner)} sacks ${n(e.hero)?"you":"the quarterback"}.`:`${a(e.hero)} ${n(e.hero)?"are":"is"} sacked.`;default:return`${a(e.hero)} in X's and O's.`}}const f=Object.freeze({catch:"What a catch in X's and O's!",pick:"Picked off in X's and O's!",fifty:"Fifty points in X's and O's!",tackle:"What a hit in X's and O's!",sack:"Sacked in X's and O's!",release:"Let it fly in X's and O's!"});export function photoShareText(e,r=""){const n=f[e]||"A moment from X's and O's.";return r?`${n} ${r}`:n}const u=Object.freeze({catch:"Want to be the one making the catch?",pick:"Want to be the one picking it off?",fifty:"Want to be the one going in for fifty?",tackle:"Want to be the one making the hit?",sack:"Want to be the one making the sack?",release:"Want to be the one throwing it?"});export function photoNudge(e){return u[e]||"Want to be in the picture?"}
